1	import type { ActionFunctionArgs, LoaderFunctionArgs } from "react-router";
2	import db from "../db.server";
3	
4	// ---------------------------------------------------------------------------
5	// CORS
6	// ---------------------------------------------------------------------------
7	
8	const CORS_HEADERS = {
9	  "Access-Control-Allow-Origin": "*",
10	  "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
11	  "Access-Control-Allow-Headers": "Content-Type",
12	};
13	
14	// ---------------------------------------------------------------------------
15	// Validation
16	// ---------------------------------------------------------------------------
17	
18	const SHOP_RE = /^[a-zA-Z0-9][a-zA-Z0-9-]*\.myshopify\.com$/;
19	
20	// ---------------------------------------------------------------------------
21	// Types
22	// ---------------------------------------------------------------------------
23	
24	type GenderInput = "male" | "female" | "unisex";
25	type GenderCalc = "male" | "female";
26	
27	interface RecommendRequestBody {
28	  shop: string;
29	  chartId: string;
30	  height: number;
31	  weight: number;
32	  unit: "metric" | "imperial";
33	  gender: GenderInput;
34	  bodyType: "slim" | "average" | "athletic" | "plus";
35	}
36	
37	interface EstimatedMeasurements {
38	  chest: number;
39	  waist: number;
40	  hips: number;
41	  inseam: number;
42	}
43	
44	interface SizeConfidence {
45	  size: string;
46	  confidence: number;
47	}
48	
49	interface RecommendResponse {
50	  recommendedSize: string;
51	  confidence: number;
52	  alternatives: SizeConfidence[];
53	  measurements: EstimatedMeasurements;
54	}
55	
56	interface ChartData {
57	  headers: string[];
58	  units: { default: string; available: string[] };
59	  rows: Record<string, string>[];
60	}
61	
62	// ---------------------------------------------------------------------------
63	// Body proportion model
64	// Based on standard anthropometric body measurement ratios.
65	// Returns estimated measurements in inches.
66	// ---------------------------------------------------------------------------
67	
68	function estimateMeasurements(
69	  heightIn: number,
70	  weightLbs: number,
71	  gender: GenderCalc,
72	  bodyType: RecommendRequestBody["bodyType"],
73	): EstimatedMeasurements {
74	  // BMI-based body shape coefficient
75	  const heightFt = heightIn / 12;
76	  const bmi = (weightLbs / (heightFt * heightFt)) * 703;
77	
78	  // Base proportions derived from published anthropometric studies (ANSUR II)
79	  // Chest = height * ratio + weight modifier
80	  const bodyTypeModifiers: Record<
81	    RecommendRequestBody["bodyType"],
82	    { chest: number; waist: number; hips: number }
83	  > = {
84	    slim: { chest: -1.5, waist: -1.5, hips: -1.5 },
85	    average: { chest: 0, waist: 0, hips: 0 },
86	    athletic: { chest: 1.5, waist: -1.0, hips: 0.5 },
87	    plus: { chest: 2.5, waist: 3.0, hips: 3.0 },
88	  };
89	
90	  const mod = bodyTypeModifiers[bodyType];
91	
92	  // Gender-specific base ratios
93	  const isFemale = gender === "female";
94	
95	  // Chest estimation: height coefficient + BMI scaling
96	  const baseChest = isFemale
97	    ? heightIn * 0.485 + bmi * 0.3
98	    : heightIn * 0.52 + bmi * 0.28;
99	
100	  // Waist: smaller ratio than chest, more BMI-sensitive
101	  const baseWaist = isFemale
102	    ? heightIn * 0.38 + bmi * 0.38
103	    : heightIn * 0.42 + bmi * 0.36;
104	
105	  // Hips: slightly larger for female, similar to chest for male
106	  const baseHips = isFemale
107	    ? heightIn * 0.52 + bmi * 0.32
108	    : heightIn * 0.49 + bmi * 0.28;
109	
110	  // Inseam: roughly 45-47% of height
111	  const baseInseam = heightIn * (isFemale ? 0.454 : 0.47);
112	
113	  return {
114	    chest: Math.round((baseChest + mod.chest) * 10) / 10,
115	    waist: Math.round((baseWaist + mod.waist) * 10) / 10,
116	    hips: Math.round((baseHips + mod.hips) * 10) / 10,
117	    inseam: Math.round(baseInseam * 10) / 10,
118	  };
119	}
120	
121	// ---------------------------------------------------------------------------
122	// Convert height/weight to inches/lbs (imperial baseline)
123	// ---------------------------------------------------------------------------
124	
125	function toImperial(
126	  height: number,
127	  weight: number,
128	  unit: RecommendRequestBody["unit"],
129	): { heightIn: number; weightLbs: number } {
130	  if (unit === "imperial") {
131	    return { heightIn: height, weightLbs: weight };
132	  }
133	  // metric: height in cm, weight in kg
134	  return {
135	    heightIn: height / 2.54,
136	    weightLbs: weight * 2.20462,
137	  };
138	}
139	
140	// ---------------------------------------------------------------------------
141	// Parse a measurement string like "34-36" or "34" into a numeric midpoint
142	// ---------------------------------------------------------------------------
143	
144	function parseMeasurement(raw: string): number | null {
145	  if (!raw || typeof raw !== "string") return null;
146	  const cleaned = raw.trim().replace(/[^\d.-]/g, " ").trim();
147	  const parts = cleaned.split(/[\s-]+/).filter((p) => p.length > 0);
148	  const nums = parts.map(Number).filter((n) => !isNaN(n) && n > 0);
149	  if (nums.length === 0) return null;
150	  if (nums.length === 1) return nums[0];
151	  // Average of range
152	  return nums.reduce((a, b) => a + b, 0) / nums.length;
153	}
154	
155	// ---------------------------------------------------------------------------
156	// Score a single chart row against estimated measurements
157	// Returns a confidence score 0–1
158	// ---------------------------------------------------------------------------
159	
160	function scoreRow(
161	  row: Record<string, string>,
162	  measurements: EstimatedMeasurements,
163	  chartUnitsDefault: string,
164	): number {
165	  // Convert measurements to cm if the chart uses cm
166	  const factor = chartUnitsDefault === "cm" ? 2.54 : 1;
167	  const target = {
168	    chest: measurements.chest * factor,
169	    waist: measurements.waist * factor,
170	    hips: measurements.hips * factor,
171	    inseam: measurements.inseam * factor,
172	  };
173	
174	  // Map column names (case-insensitive) to measurement types
175	  const COLUMN_MAP: Record<string, keyof typeof target> = {
176	    chest: "chest",
177	    bust: "chest",
178	    waist: "waist",
179	    hips: "hips",
180	    hip: "hips",
181	    inseam: "inseam",
182	  };
183	
184	  let totalScore = 0;
185	  let scoredColumns = 0;
186	
187	  for (const [colName, cellValue] of Object.entries(row)) {
188	    const normalised = colName.toLowerCase().replace(/[^a-z]/g, "");
189	    const measureKey = COLUMN_MAP[normalised];
190	    if (!measureKey) continue;
191	
192	    const measured = parseMeasurement(cellValue);
193	    if (measured === null) continue;
194	
195	    const actual = target[measureKey];
196	    // Tolerance: ±2in (or ±5cm) scores 1.0, degrades linearly to 0 at ±6in (±15cm)
197	    const tol = chartUnitsDefault === "cm" ? 5 : 2;
198	    const maxDelta = chartUnitsDefault === "cm" ? 15 : 6;
199	    const delta = Math.abs(actual - measured);
200	    const colScore = delta <= tol ? 1.0 : Math.max(0, 1 - (delta - tol) / (maxDelta - tol));
201	
202	    totalScore += colScore;
203	    scoredColumns++;
204	  }
205	
206	  if (scoredColumns === 0) return 0;
207	  return totalScore / scoredColumns;
208	}
209	
210	// ---------------------------------------------------------------------------
211	// Main recommendation engine
212	// ---------------------------------------------------------------------------
213	
214	function recommendSize(
215	  chartData: ChartData,
216	  measurements: EstimatedMeasurements,
217	): { recommendedSize: string; confidence: number; alternatives: SizeConfidence[] } {
218	  const sizeHeader = chartData.headers.find((h) =>
219	    ["size", "size label", "label"].includes(h.toLowerCase()),
220	  );
221	
222	  if (!sizeHeader || chartData.rows.length === 0) {
223	    return { recommendedSize: "N/A", confidence: 0, alternatives: [] };
224	  }
225	
226	  const unitsDefault = chartData.units?.default ?? "in";
227	
228	  // Score each row
229	  const scored: SizeConfidence[] = chartData.rows
230	    .map((row) => {
231	      const sizeName = row[sizeHeader];
232	      if (!sizeName) return null;
233	      const confidence = Math.round(scoreRow(row, measurements, unitsDefault) * 100) / 100;
234	      return { size: sizeName, confidence };
235	    })
236	    .filter((s): s is SizeConfidence => s !== null);
237	
238	  if (scored.length === 0) {
239	    return { recommendedSize: "N/A", confidence: 0, alternatives: [] };
240	  }
241	
242	  // Sort descending by confidence
243	  scored.sort((a, b) => b.confidence - a.confidence);
244	
245	  const best = scored[0];
246	  // Alternatives: second and third best with confidence > 0.3
247	  const alternatives = scored
248	    .slice(1)
249	    .filter((s) => s.confidence > 0.3)
250	    .slice(0, 2);
251	
252	  return {
253	    recommendedSize: best.size,
254	    confidence: best.confidence,
255	    alternatives,
256	  };
257	}
258	
259	// ---------------------------------------------------------------------------
260	// Preflight
261	// ---------------------------------------------------------------------------
262	
263	export const loader = async ({ request }: LoaderFunctionArgs) => {
264	  if (request.method === "OPTIONS") {
265	    return new Response(null, { status: 204, headers: CORS_HEADERS });
266	  }
267	  return Response.json(
268	    { error: "Method not allowed" },
269	    { status: 405, headers: CORS_HEADERS },
270	  );
271	};
272	
273	// ---------------------------------------------------------------------------
274	// Action — POST /api/recommend
275	// Body JSON: { shop, height, weight, unit, gender, bodyType, chartId }
276	// ---------------------------------------------------------------------------
277	
278	export const action = async ({ request }: ActionFunctionArgs) => {
279	  if (request.method === "OPTIONS") {
280	    return new Response(null, { status: 204, headers: CORS_HEADERS });
281	  }
282	
283	  if (request.method !== "POST") {
284	    return Response.json(
285	      { error: "Method not allowed" },
286	      { status: 405, headers: CORS_HEADERS },
287	    );
288	  }
289	
290	  let body: Partial<RecommendRequestBody>;
291	
292	  try {
293	    body = (await request.json()) as Partial<RecommendRequestBody>;
294	  } catch {
295	    return Response.json(
296	      { error: "Invalid JSON body" },
297	      { status: 400, headers: CORS_HEADERS },
298	    );
299	  }
300	
301	  const { shop, chartId, height, weight, unit, gender, bodyType } = body;
302	
303	  // Validate shop
304	  if (!shop || !SHOP_RE.test(shop)) {
305	    return Response.json(
306	      { error: "Invalid or missing shop parameter" },
307	      { status: 400, headers: CORS_HEADERS },
308	    );
309	  }
310	
311	  // Validate required fields
312	  if (!chartId) {
313	    return Response.json(
314	      { error: "chartId is required" },
315	      { status: 400, headers: CORS_HEADERS },
316	    );
317	  }
318	  if (typeof height !== "number" || height <= 0) {
319	    return Response.json(
320	      { error: "height must be a positive number" },
321	      { status: 400, headers: CORS_HEADERS },
322	    );
323	  }
324	  if (typeof weight !== "number" || weight <= 0) {
325	    return Response.json(
326	      { error: "weight must be a positive number" },
327	      { status: 400, headers: CORS_HEADERS },
328	    );
329	  }
330	  if (!unit || !["metric", "imperial"].includes(unit)) {
331	    return Response.json(
332	      { error: "unit must be 'metric' or 'imperial'" },
333	      { status: 400, headers: CORS_HEADERS },
334	    );
335	  }
336	  if (!gender || !["male", "female", "unisex"].includes(gender)) {
337	    return Response.json(
338	      { error: "gender must be 'male', 'female', or 'unisex'" },
339	      { status: 400, headers: CORS_HEADERS },
340	    );
341	  }
342	  if (!bodyType || !["slim", "average", "athletic", "plus"].includes(bodyType)) {
343	    return Response.json(
344	      { error: "bodyType must be 'slim', 'average', 'athletic', or 'plus'" },
345	      { status: 400, headers: CORS_HEADERS },
346	    );
347	  }
348	
349	  // Range validation — reject impossible measurements
350	  const isMetric = unit === "metric";
351	  const minHeight = isMetric ? 100 : 40;
352	  const maxHeight = isMetric ? 250 : 98;
353	  const minWeight = isMetric ? 30 : 66;
354	  const maxWeight = isMetric ? 300 : 660;
355	
356	  if (height < minHeight || height > maxHeight) {
357	    return Response.json(
358	      { error: `height must be between ${minHeight} and ${maxHeight} ${isMetric ? "cm" : "inches"}` },
359	      { status: 400, headers: CORS_HEADERS },
360	    );
361	  }
362	  if (weight < minWeight || weight > maxWeight) {
363	    return Response.json(
364	      { error: `weight must be between ${minWeight} and ${maxWeight} ${isMetric ? "kg" : "lbs"}` },
365	      { status: 400, headers: CORS_HEADERS },
366	    );
367	  }
368	
369	  try {
370	    // Check recommender is enabled for this shop
371	    const recommenderConfig = await db.recommenderConfig.findUnique({
372	      where: { shop },
373	    });
374	
375	    if (!recommenderConfig?.enabled) {
376	      return Response.json(
377	        { error: "AI recommender is not enabled for this shop" },
378	        { status: 403, headers: CORS_HEADERS },
379	      );
380	    }
381	
382	    // Fetch the chart scoped to this shop
383	    const chart = await db.sizeChart.findFirst({
384	      where: { id: chartId, shop, status: "active" },
385	    });
386	
387	    if (!chart) {
388	      return Response.json(
389	        { error: "Chart not found" },
390	        { status: 404, headers: CORS_HEADERS },
391	      );
392	    }
393	
394	    // Parse chart data
395	    let chartData: ChartData;
396	    try {
397	      const parsed = JSON.parse(chart.data) as unknown;
398	      if (
399	        parsed !== null &&
400	        typeof parsed === "object" &&
401	        !Array.isArray(parsed)
402	      ) {
403	        const obj = parsed as Record<string, unknown>;
404	        chartData = {
405	          headers: Array.isArray(obj.headers) ? (obj.headers as string[]) : [],
406	          units:
407	            obj.units !== null &&
408	            typeof obj.units === "object" &&
409	            !Array.isArray(obj.units)
410	              ? (obj.units as { default: string; available: string[] })
411	              : { default: "in", available: ["in", "cm"] },
412	          rows: Array.isArray(obj.rows)
413	            ? (obj.rows as Record<string, string>[])
414	            : [],
415	        };
416	      } else {
417	        chartData = { headers: [], units: { default: "in", available: ["in", "cm"] }, rows: [] };
418	      }
419	    } catch {
420	      chartData = { headers: [], units: { default: "in", available: ["in", "cm"] }, rows: [] };
421	    }
422	
423	    // Convert inputs to imperial baseline
424	    const { heightIn, weightLbs } = toImperial(height, weight, unit);
425	
426	    // Map unisex → female as a neutral default (average body proportions)
427	    const calcGender: GenderCalc = gender === "male" ? "male" : "female";
428	
429	    // Estimate body measurements
430	    // bodyType is validated above; cast to satisfy strict narrowing
431	    const validBodyType = bodyType as RecommendRequestBody["bodyType"];
432	    const measurements = estimateMeasurements(
433	      heightIn,
434	      weightLbs,
435	      calcGender,
436	      validBodyType,
437	    );
438	
439	    // Run recommendation
440	    const { recommendedSize, confidence, alternatives } = recommendSize(
441	      chartData,
442	      measurements,
443	    );
444	
445	    const response: RecommendResponse = {
446	      recommendedSize,
447	      confidence,
448	      alternatives,
449	      measurements,
450	    };
451	
452	    return Response.json(response, { headers: CORS_HEADERS });
453	  } catch (error) {
454	    console.error("[api.recommend]", error);
455	    return Response.json(
456	      { error: "Unable to process recommendation. Please try again." },
457	      { status: 500, headers: CORS_HEADERS },
458	    );
459	  }
460	};
