54	// ---------------------------------------------------------------------------
55	// getAnalyticsSummary
56	// Returns totals for each event type within the given date range.
57	// ---------------------------------------------------------------------------
58	
59	export async function getAnalyticsSummary(
60	  shop: string,
61	  dateRange: DateRange,
62	): Promise<AnalyticsSummary> {
63	  const where = {
64	    shop,
65	    createdAt: { gte: dateRange.from, lte: dateRange.to },
66	  };
67	
68	  const [views, clicks, recommendations, conversions, dismissals] =
69	    await Promise.all([
70	      db.analyticsEvent.count({ where: { ...where, eventType: "view" } }),
71	      db.analyticsEvent.count({ where: { ...where, eventType: "click" } }),
72	      db.analyticsEvent.count({ where: { ...where, eventType: "recommend" } }),
73	      db.analyticsEvent.count({ where: { ...where, eventType: "convert" } }),
74	      db.analyticsEvent.count({ where: { ...where, eventType: "dismiss" } }),
75	    ]);
76	
77	  return {
78	    totalViews: views,
79	    totalClicks: clicks,
80	    totalRecommendations: recommendations,
81	    totalConversions: conversions,
82	    totalDismissals: dismissals,
83	  };
84	}
