237	// ---------------------------------------------------------------------------
238	// getProductPerformance
239	// Returns per-product event counts, scoped to a shop and date range.
240	// Useful for identifying which products benefit most from size charts.
241	// ---------------------------------------------------------------------------
242	
243	export async function getProductPerformance(
244	  shop: string,
245	  dateRange: DateRange,
246	): Promise<ProductPerformance[]> {
247	  const where = {
248	    shop,
249	    productId: { not: null },
250	    createdAt: { gte: dateRange.from, lte: dateRange.to },
251	  };
252	
253	  const eventTypes: string[] = ["view", "click", "recommend", "convert"];
254	
255	  const groups = await Promise.all(
256	    eventTypes.map((eventType) =>
257	      db.analyticsEvent.groupBy({
258	        by: ["productId"],
259	        where: { ...where, eventType },
260	        _count: { id: true },
261	      }),
262	    ),
263	  );
264	
265	  const [viewGroups, clickGroups, recommendGroups, convertGroups] = groups;
266	
267	  type ProductMap = Map<string, number>;
268	
269	  const toProductMap = (
270	    g: { productId: string | null; _count: { id: number } }[],
271	  ): ProductMap => {
272	    const m: ProductMap = new Map();
273	    for (const row of g) {
274	      if (row.productId) m.set(row.productId, row._count.id);
275	    }
276	    return m;
277	  };
278	
279	  const viewMap = toProductMap(viewGroups);
280	  const clickMap = toProductMap(clickGroups);
281	  const recommendMap = toProductMap(recommendGroups);
282	  const convertMap = toProductMap(convertGroups);
283	
284	  // Union of all product IDs across event types
285	  const allProductIds = new Set<string>([
286	    ...viewMap.keys(),
287	    ...clickMap.keys(),
288	    ...recommendMap.keys(),
289	    ...convertMap.keys(),
290	  ]);
291	
292	  return [...allProductIds]
293	    .map((productId) => ({
294	      productId,
295	      views: viewMap.get(productId) ?? 0,
296	      clicks: clickMap.get(productId) ?? 0,
297	      recommendations: recommendMap.get(productId) ?? 0,
298	      conversions: convertMap.get(productId) ?? 0,
299	    }))
300	    .sort((a, b) => b.views - a.views);
301	}
